class LibraryMember {protected String id;protected int limit;private int borrowed;public LibraryMember(String i,int l){if(i==null||i.trim().length()<4)throw new IllegalArgumentException("Invalid ID");if(l<=0)throw new IllegalArgumentException("Limit must be positive");id=i;limit=l;}public void borrowBook(){if(borrowed>=limit)throw new IllegalStateException("Limit reached");borrowed++;}public int getBooksBorrowed(){return borrowed;}public void displayInfo(){System.out.print("General Member | Books Borrowed: "+borrowed);}}
class StudentMember extends LibraryMember {protected String course;public StudentMember(String i,int l,String c){super(i,l);course=c;}@Override public void displayInfo(){System.out.print("Student Member | Course: "+course+" | Books Borrowed: "+getBooksBorrowed());}}
class HonorsStudentMember extends StudentMember {private int bonusLimit;public HonorsStudentMember(String i,int l,String c,int b){super(i,l,c);bonusLimit=b;}@Override public void displayInfo(){System.out.print("Honors Student Member | Course: "+course+" | Bonus Limit: "+bonusLimit+" | Books Borrowed: "+getBooksBorrowed());}}
class FacultyMember extends LibraryMember {private String department;public FacultyMember(String i,int l,String d){super(i,l);department=d;}@Override public void displayInfo(){System.out.print("Faculty Member | Department: "+department+" | Books Borrowed: "+getBooksBorrowed());}}
public class ThreeBranchesMembershipTreeMain {public static String classifyGeneration(LibraryMember m){if(m instanceof HonorsStudentMember)return "Multilevel descendant (3 generations deep)";if(m instanceof FacultyMember)return "Hierarchical sibling (independent branch)";if(m instanceof StudentMember)return "Student generation";return "Base generation";}public static int getTotalBooksBorrowed(LibraryMember[] ms){int n=0;for(LibraryMember m:ms)n+=m.getBooksBorrowed();return n;}public static void main(String[] a){StudentMember s=new StudentMember("STU2",3,"CSE");HonorsStudentMember h=new HonorsStudentMember("STU3",3,"ECE",2);FacultyMember f=new FacultyMember("STU4",5,"Physics");s.borrowBook();s.borrowBook();h.borrowBook();for(int i=0;i<3;i++)f.borrowBook();System.out.println(classifyGeneration(h));System.out.println(classifyGeneration(f));System.out.println(getTotalBooksBorrowed(new LibraryMember[]{s,h,f}));}}
